window.LAB_LIBRARY={"papers":[{"id":"pub00001","ax":"2609.02734","key":null,"t":"LoRA-TSD: Tangent-Space Spectral Descent for LoRA via Muon-Style Updates","au":"Dmitrii Andriianov, Andrey Veprikov, Aleksandr Beznosikov","y":2026,"v":"Препринт · arXiv","s":"LoRA-TSD переносит спектральный шаг Muon в касательное пространство матриц фиксированного ранга. Обновление возвращается в факторы LoRA без работы с полной матрицей весов.","sr":"LoRA-TSD переносит спектральный шаг Muon в касательное пространство матриц фиксированного ранга. Обновление возвращается в факторы LoRA без работы с полной матрицей весов.","ab":"LoRA-TSD переносит спектральный шаг Muon в касательное пространство матриц фиксированного ранга. Обновление возвращается в факторы LoRA без работы с полной матрицей весов.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"LoRA-TSD строит шаг в касательном пространстве матрицы обновления LoRA и выбирает направление спуска в спектральной норме.","q":"","v":false,"source_url":"https://arxiv.org/abs/2609.02734","locator":"Аннотация arXiv"},{"k":"method","s":"Специальная ретракция возвращает касательный шаг в факторы LoRA, не требуя дорогих операций с полной матрицей весов.","q":"","v":false,"source_url":"https://arxiv.org/abs/2609.02734","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Для варианта в норме Фробениуса авторы восстанавливают LoRA-Pro. Сходимость LoRA-Pro и LoRA-TSD анализируется через риманов градиент.","q":"","v":false,"source_url":"https://arxiv.org/abs/2609.02734","locator":"Аннотация arXiv"},{"k":"empirical","s":"На шести задачах здравого смысла и логического вывода с Llama-3.2-1B, Llama-3.1-8B и Qwen3-32B авторы сообщают преимущество LoRA-TSD над сравниваемыми оптимизаторами LoRA.","q":"","v":false,"source_url":"https://arxiv.org/abs/2609.02734","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2609.02734","venue_url":"https://arxiv.org/abs/2609.02734","code_url":"https://github.com/brain-lab-research/LoRA-TSD","reading_scope":"Аннотация arXiv"},{"id":"pub00002","ax":"2605.31371","key":null,"t":"Softsign: Smooth Sign in Your Optimizer For Better Parameter Heterogeneity Handling","au":"Dmitrii Feoktistov, Timofey Belinsky, Andrey Veprikov, Amir Zainullin, Aleksandr Beznosikov","y":2026,"v":"ICML 2026","s":"Softsign заменяет жёсткий знак градиента плавной функцией. Температура регулирует, насколько шаг сохраняет величину градиента; для матричных параметров предложен SoftMuon.","sr":"Softsign заменяет жёсткий знак градиента плавной функцией. Температура регулирует, насколько шаг сохраняет величину градиента; для матричных параметров предложен SoftMuon.","ab":"Softsign заменяет жёсткий знак градиента плавной функцией. Температура регулирует, насколько шаг сохраняет величину градиента; для матричных параметров предложен SoftMuon.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":5,"ns":1,"nm":0,"c":[{"k":"method","s":"SoftSignum сглаживает знак градиента: температура управляет переходом от почти знакового шага к шагу, чувствительному к величине градиента.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"Аннотация arXiv"},{"k":"method","s":"Квантильная адаптация температуры подстраивает Softsign под распределение величин градиента и неоднородность параметров.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"Аннотация arXiv"},{"k":"method","s":"SoftMuon переносит идею гладкого знака на матричные обновления Muon.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Авторы связывают сглаженные направления с сильно выпуклой регуляризацией и доказывают сходимость в невыпуклой стохастической постановке.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"Аннотация arXiv"},{"k":"empirical","s":"В приведённых экспериментах, включая обучение языковых моделей, Softsign улучшает результаты сравниваемых знаковых оптимизаторов.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2605.31371","venue_url":"https://icml.cc/Downloads/2026","code_url":"https://github.com/brain-lab-research/softsign","reading_scope":"Аннотация arXiv"},{"id":"pub00003","ax":"2605.22644","key":null,"t":"Why SGD is not Brownian Motion: A New Perspective on Stochastic Dynamics","au":"Igor Ignashin, Anna Radovskaya, Andrew Semenov, Egor Lopatin, Stanislav Potapov, Aleksandr Kovalenko, Andrey Veprikov, Aleksandr Shestakov, Andrey Leonidov, Aleksandr Beznosikov","y":2026,"v":"Препринт · arXiv","s":"Работа исследует стохастическую динамику SGD с конечным шагом. Дискретное обучение моделируется через флуктуации ландшафта функции потерь, а не только непрерывное броуновское приближение.","sr":"Работа исследует стохастическую динамику SGD с конечным шагом. Дискретное обучение моделируется через флуктуации ландшафта функции потерь, а не только непрерывное броуновское приближение.","ab":"Работа исследует стохастическую динамику SGD с конечным шагом. Дискретное обучение моделируется через флуктуации ландшафта функции потерь, а не только непрерывное броуновское приближение.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"theoretical","s":"Дискретное уравнение Фоккера — Планка для SGD отличается от непрерывного приближения Ланжевена в членах второго порядка по шагу обучения.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.22644","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Разложение по собственным направлениям около критической точки описывает, как кривизна влияет на флуктуации параметров SGD.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.22644","locator":"Аннотация arXiv"},{"k":"theoretical","s":"В плоских направлениях рассмотренная модель предсказывает рост дисперсии с коэффициентом диффузии, зависящим от шага обучения.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.22644","locator":"Аннотация arXiv"},{"k":"empirical","s":"Предсказания модели сопоставлены с экспериментами в компьютерном зрении и обработке языка; это проверка исследованных режимов SGD.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.22644","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2605.22644","venue_url":"https://arxiv.org/abs/2605.22644","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00004","ax":"2605.19811","key":null,"t":"LionMuon: Alternating Spectral and Sign Descent for Efficient Training","au":"Arman Bolatov, Artem Riabinin, Nikita Kornilov, Andrey Veprikov, Samuel Horváth, Martin Takáč, Aleksandr Beznosikov","y":2026,"v":"Препринт · arXiv","s":"LionMuon чередует спектральные шаги Muon и знаковые шаги Lion. Один общий буфер импульса позволяет сочетать направления с разной вычислительной стоимостью.","sr":"LionMuon чередует спектральные шаги Muon и знаковые шаги Lion. Один общий буфер импульса позволяет сочетать направления с разной вычислительной стоимостью.","ab":"LionMuon чередует спектральные шаги Muon и знаковые шаги Lion. Один общий буфер импульса позволяет сочетать направления с разной вычислительной стоимостью.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"LionMuon периодически чередует Lion и Muon, используя общий буфер импульса вместо двух независимых состояний оптимизаторов.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.19811","locator":"Аннотация arXiv"},{"k":"method","s":"Период чередования регулирует долю дорогих спектральных шагов; SignMuon использует знаковое направление с одной экспоненциальной средней.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.19811","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Оценка сходимости учитывает усреднённые по периоду характеристики гладкости и шума, в том числе шум с тяжёлыми хвостами.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.19811","locator":"Аннотация arXiv"},{"k":"empirical","s":"В экспериментах с языковыми моделями авторы показывают режимы LionMuon с меньшей функцией потерь и меньшими затратами вычислений по сравнению с выбранными базовыми методами.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.19811","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2605.19811","venue_url":"https://arxiv.org/abs/2605.19811","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00005","ax":"2602.16456","key":null,"t":"Beyond SGD, Without SVD: Proximal Subspace Iteration LoRA with Diagonal Fractional K-FAC","au":"Abdulla Jasem Almansoori, Maria Ivanova, Andrey Veprikov, Aleksandr Beznosikov, Samuel Horváth, Martin Takáč","y":2026,"v":"Препринт · arXiv","s":"Проксимальное обновление LoRA решается чередующимися шагами по факторам. Метод LoRSum связывает такую итерацию подпространства с диагональным дробным K-FAC и низкоранговым импульсом.","sr":"Проксимальное обновление LoRA решается чередующимися шагами по факторам. Метод LoRSum связывает такую итерацию подпространства с диагональным дробным K-FAC и низкоранговым импульсом.","ab":"Проксимальное обновление LoRA решается чередующимися шагами по факторам. Метод LoRSum связывает такую итерацию подпространства с диагональным дробным K-FAC и низкоранговым импульсом.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"Чередующееся решение проксимальной задачи LoRA интерпретируется как неявная блочная степенная итерация и обходится без полного SVD.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.16456","locator":"Аннотация arXiv"},{"k":"method","s":"Диагональные дробные предобуславливатели K-FAC задают геометрию шага при сохранении низкорангового представления обновления.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.16456","locator":"Аннотация arXiv"},{"k":"method","s":"LoRSum хранит импульс в низкоранговой форме, чтобы не возвращать полное матричное состояние при дообучении.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.16456","locator":"Аннотация arXiv"},{"k":"empirical","s":"В работе сравниваются качество и стоимость дообучения на CIFAR-100, GLUE, SQuAD v2 и WikiText-103.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.16456","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2602.16456","venue_url":"https://arxiv.org/abs/2602.16456","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00006","ax":"2602.13659","key":null,"t":"Zero-Order Optimization for LLM Fine-Tuning via Learnable Direction Sampling","au":"Valery Parfenov, Grigoriy Evseev, Andrey Veprikov, Nikolay Bushkov, Stanislav Moiseev, Aleksandr Beznosikov","y":2026,"v":"Препринт · arXiv","s":"Направления для безградиентного дообучения LLM выбирает обучаемая политика. Она меняет распределение возмущений, по которым оценивается направление улучшения функции потерь.","sr":"Направления для безградиентного дообучения LLM выбирает обучаемая политика. Она меняет распределение возмущений, по которым оценивается направление улучшения функции потерь.","ab":"Направления для безградиентного дообучения LLM выбирает обучаемая политика. Она меняет распределение возмущений, по которым оценивается направление улучшения функции потерь.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"Вместо фиксированного случайного распределения направлений используется обучаемая политика выбора возмущений параметров.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.13659","locator":"Аннотация arXiv"},{"k":"method","s":"Оценка направления обновления строится по значениям функции потерь и не требует обратного распространения через языковую модель.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.13659","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Анализ связывает адаптацию распределения направлений со снижением дисперсии и ослаблением явной зависимости оценок от размерности.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.13659","locator":"Аннотация arXiv"},{"k":"empirical","s":"Преимущества обучаемых направлений проверены в приведённых задачах безградиентного дообучения языковых моделей.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.13659","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2602.13659","venue_url":"https://arxiv.org/abs/2602.13659","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00007","ax":"2602.05813","key":null,"t":"Where Does Warm-Up Come From? Adaptive Scheduling for Norm-Constrained Optimizers","au":"Artem Riabinin, Andrey Veprikov, Arman Bolatov, Martin Takáč, Aleksandr Beznosikov","y":2026,"v":"Препринт · arXiv","s":"Работа выводит разогрев и последующее снижение шага из модели меняющейся локальной кривизны. Адаптивное расписание предназначено для оптимизаторов с ограничением нормы направления.","sr":"Работа выводит разогрев и последующее снижение шага из модели меняющейся локальной кривизны. Адаптивное расписание предназначено для оптимизаторов с ограничением нормы направления.","ab":"Работа выводит разогрев и последующее снижение шага из модели меняющейся локальной кривизны. Адаптивное расписание предназначено для оптимизаторов с ограничением нормы направления.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"theoretical","s":"В принятой модели обобщённой гладкости локальная кривизна уменьшается вместе с разрывом до оптимума; это даёт основание для роста шага в начале обучения.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.05813","locator":"Аннотация arXiv"},{"k":"method","s":"Адаптивное расписание сначала увеличивает шаг, затем уменьшает его. Продолжительность разогрева определяется самим правилом обновления.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.05813","locator":"Аннотация arXiv"},{"k":"method","s":"Расписание разогрева использует стандартные параметры оптимизатора и не требует отдельного перебора длительности warm-up.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.05813","locator":"Аннотация arXiv"},{"k":"empirical","s":"В экспериментах с моделями Llama авторы получают качество на уровне лучших вручную подобранных расписаний или выше при исследованных настройках.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.05813","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2602.05813","venue_url":"https://arxiv.org/abs/2602.05813","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00008","ax":"2601.05398","key":null,"t":"Markovian Compression: Looking to the Past Helps Accelerate the Future","au":"Andrey Veprikov, Vladimir Solodkin, Mikhail Rudakov, Petr Babkin, Aleksandr Beznosikov","y":2026,"v":"UAI 2026","s":"Марковское сжатие использует историю предыдущих шагов при передаче градиентов. Работа рассматривает QSGD и его вариант с импульсом с точки зрения стоимости коммуникации и сходимости.","sr":"Марковское сжатие использует историю предыдущих шагов при передаче градиентов. Работа рассматривает QSGD и его вариант с импульсом с точки зрения стоимости коммуникации и сходимости.","ab":"Марковское сжатие использует историю предыдущих шагов при передаче градиентов. Работа рассматривает QSGD и его вариант с импульсом с точки зрения стоимости коммуникации и сходимости.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"Марковский компрессор учитывает предыдущие итерации, поэтому ошибки сжатия не моделируются как независимые на каждом шаге.","q":"","v":false,"source_url":"https://arxiv.org/abs/2601.05398","locator":"Аннотация arXiv"},{"k":"method","s":"Предложенный подход применяется к квантованному SGD и его варианту с импульсом.","q":"","v":false,"source_url":"https://arxiv.org/abs/2601.05398","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Получены оценки сходимости для невыпуклых, сильно выпуклых задач и функций с условием Поляка — Лоясиевича.","q":"","v":false,"source_url":"https://arxiv.org/abs/2601.05398","locator":"Аннотация arXiv"},{"k":"empirical","s":"Эксперименты с ResNet-18 на CIFAR-10 и DeBERTa-v3 на GLUE проверяют, как использование истории сжатия влияет на обучение.","q":"","v":false,"source_url":"https://arxiv.org/abs/2601.05398","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2601.05398","venue_url":"https://proceedings.mlr.press/v337/veprikov26a.html","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00009","ax":"2511.06477","key":null,"t":"DyKAF: Dynamical Kronecker Approximation of the Fisher Information Matrix for Gradient Preconditioning","au":"Nikolay Yudin, Ekaterina Grishina, Andrey Veprikov, Alexandr Beznosikov, Maxim Rakhuba","y":2025,"v":"Препринт · arXiv","s":"DyKAF динамически приближает матрицу Фишера кронекеровскими факторами. Обновление факторов опирается на интеграторы с расщеплением проектора и используется для предобуславливания градиента.","sr":"DyKAF динамически приближает матрицу Фишера кронекеровскими факторами. Обновление факторов опирается на интеграторы с расщеплением проектора и используется для предобуславливания градиента.","ab":"DyKAF динамически приближает матрицу Фишера кронекеровскими факторами. Обновление факторов опирается на интеграторы с расщеплением проектора и используется для предобуславливания градиента.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"DyKAF представляет приближение матрицы Фишера через кронекеровские факторы и обновляет их по мере обучения.","q":"","v":false,"source_url":"https://arxiv.org/abs/2511.06477","locator":"Аннотация arXiv"},{"k":"method","s":"Для динамической аппроксимации используются интеграторы с расщеплением проектора, связывающие обновление факторов с геометрией матричного многообразия.","q":"","v":false,"source_url":"https://arxiv.org/abs/2511.06477","locator":"Аннотация arXiv"},{"k":"empirical","s":"Авторы сравнивают точность кронекеровской аппроксимации DyKAF с альтернативами на исследованных задачах.","q":"","v":false,"source_url":"https://arxiv.org/abs/2511.06477","locator":"Аннотация arXiv"},{"k":"empirical","s":"Предобуславливатель DyKAF проверен в предобучении и дообучении языковых моделей; результаты относятся к приведённым в работе конфигурациям.","q":"","v":false,"source_url":"https://arxiv.org/abs/2511.06477","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2511.06477","venue_url":"https://arxiv.org/abs/2511.06477","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00010","ax":"2510.10777","key":null,"t":"Preconditioned Norms: A Unified Framework for Steepest Descent, Quasi-Newton and Adaptive Methods","au":"Andrey Veprikov, Arman Bolatov, Aleksandr Bogdanov, Samuel Horváth, Aleksandr Beznosikov, Martin Takáč, Slavomir Hanzely","y":2025,"v":"Препринт · arXiv","s":"Предобусловленные нормы объединяют выбор геометрии спуска и предобуславливателя. В этой схеме сопоставляются SGD, Adam, Muon и матричные методы второго порядка.","sr":"Предобусловленные нормы объединяют выбор геометрии спуска и предобуславливателя. В этой схеме сопоставляются SGD, Adam, Muon и матричные методы второго порядка.","ab":"Предобусловленные нормы объединяют выбор геометрии спуска и предобуславливателя. В этой схеме сопоставляются SGD, Adam, Muon и матричные методы второго порядка.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"theoretical","s":"Направление наискорейшего спуска определяется одновременно нормой и предобуславливателем; выбор этих двух частей объединяет несколько семейств оптимизаторов.","q":"","v":false,"source_url":"https://arxiv.org/abs/2510.10777","locator":"Аннотация arXiv"},{"k":"theoretical","s":"В общей схеме рассматриваются условия аффинной и масштабной инвариантности методов оптимизации.","q":"","v":false,"source_url":"https://arxiv.org/abs/2510.10777","locator":"Аннотация arXiv"},{"k":"method","s":"SGD, Adam, Muon, KL-Shampoo, SOAP и SPlus интерпретируются как частные варианты выбора нормы и предобуславливания.","q":"","v":false,"source_url":"https://arxiv.org/abs/2510.10777","locator":"Аннотация arXiv"},{"k":"method","s":"MuAdam и MuAdam-SANIA сочетают спектральную геометрию с адаптивным масштабированием Adam; работа проверяет эти варианты экспериментально.","q":"","v":false,"source_url":"https://arxiv.org/abs/2510.10777","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2510.10777","venue_url":"https://arxiv.org/abs/2510.10777","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00011","ax":"2509.19977","key":null,"t":"Faster Than SVD, Smarter Than SGD: The OPLoRA Alternating Update","au":"Abdulla Jasem Almansoori, Maria Ivanova, Andrey Veprikov, Aleksandr Beznosikov, Samuel Horváth, Martin Takáč","y":2025,"v":"OPT 2025 · воркшоп","s":"OPLoRA обновляет факторы адаптера чередующимся решением задач наименьших квадратов. Это позволяет приближать усечённое SVD без построения полной матрицы обновления.","sr":"OPLoRA обновляет факторы адаптера чередующимся решением задач наименьших квадратов. Это позволяет приближать усечённое SVD без построения полной матрицы обновления.","ab":"OPLoRA обновляет факторы адаптера чередующимся решением задач наименьших квадратов. Это позволяет приближать усечённое SVD без построения полной матрицы обновления.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"OPLoRA использует чередующиеся обновления факторов LoRA вместо их независимого градиентного обучения.","q":"","v":false,"source_url":"https://arxiv.org/abs/2509.19977","locator":"Аннотация arXiv"},{"k":"method","s":"Один или два шага чередующихся наименьших квадратов приближают обновление с усечённым SVD, избегая явного формирования полной матрицы.","q":"","v":false,"source_url":"https://arxiv.org/abs/2509.19977","locator":"Аннотация arXiv"},{"k":"method","s":"Низкоранговый импульс сохраняет матричное направление в компактных факторах; рассматривается также масштабирование с помощью K-FAC.","q":"","v":false,"source_url":"https://arxiv.org/abs/2509.19977","locator":"Аннотация arXiv"},{"k":"empirical","s":"OPLoRA проверен на линейных задачах, MNIST, CIFAR-100 и дообучении RoBERTa на MNLI.","q":"","v":false,"source_url":"https://arxiv.org/abs/2509.19977","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2509.19977","venue_url":"https://arxiv.org/abs/2509.19977","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00012","ax":"2508.16734","key":null,"t":"Aligning Distributionally Robust Optimization with Practical Deep Learning Needs","au":"Dmitrii Feoktistov, Igor Ignashin, Andrey Veprikov, Nikita Borovko, Alexander Bogdanov, Savelii Chezhegov, Aleksandr Beznosikov","y":2025,"v":"Препринт · arXiv","s":"ALSO адаптирует распределённо-робастную оптимизацию к обучению глубоких моделей. Группы данных получают меняющиеся веса, чтобы учитывать неоднородность ошибок.","sr":"ALSO адаптирует распределённо-робастную оптимизацию к обучению глубоких моделей. Группы данных получают меняющиеся веса, чтобы учитывать неоднородность ошибок.","ab":"ALSO адаптирует распределённо-робастную оптимизацию к обучению глубоких моделей. Группы данных получают меняющиеся веса, чтобы учитывать неоднородность ошибок.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"Групповая распределённо-робастная постановка оптимизирует обучение с учётом групп данных, на которых модель ошибается сильнее.","q":"","v":false,"source_url":"https://arxiv.org/abs/2508.16734","locator":"Аннотация arXiv"},{"k":"method","s":"ALSO адаптивно обновляет веса групп и параметры модели на основе стохастических градиентов.","q":"","v":false,"source_url":"https://arxiv.org/abs/2508.16734","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Для предложенных алгоритмов получены гарантии сходимости в невыпуклой постановке.","q":"","v":false,"source_url":"https://arxiv.org/abs/2508.16734","locator":"Аннотация arXiv"},{"k":"empirical","s":"Работа проверяет подход на задачах от табличных данных до раздельного обучения Split Learning.","q":"","v":false,"source_url":"https://arxiv.org/abs/2508.16734","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2508.16734","venue_url":"https://arxiv.org/abs/2508.16734","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00013","ax":"2506.04430","key":null,"t":"Leveraging Coordinate Momentum in SignSGD and Muon: Memory-Optimized Zero-Order","au":"Egor Petrov, Grigoriy Evseev, Aleksey Antonov, Andrey Veprikov, Nikolay Bushkov, Stanislav Moiseev, Aleksandr Beznosikov","y":2025,"v":"Препринт · arXiv","s":"Координатная память JAGUAR используется в безградиентных вариантах SignSGD и Muon. Цель — обновлять параметры по значениям функции, сохраняя информацию о ранее оценённых координатах.","sr":"Координатная память JAGUAR используется в безградиентных вариантах SignSGD и Muon. Цель — обновлять параметры по значениям функции, сохраняя информацию о ранее оценённых координатах.","ab":"Координатная память JAGUAR используется в безградиентных вариантах SignSGD и Muon. Цель — обновлять параметры по значениям функции, сохраняя информацию о ранее оценённых координатах.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"Координатный импульс JAGUAR переиспользует информацию предыдущих оценок вместо пересчёта всех координат на каждом шаге.","q":"","v":false,"source_url":"https://arxiv.org/abs/2506.04430","locator":"Аннотация arXiv"},{"k":"method","s":"Безградиентная оценка с координатной памятью применяется к знаковому обновлению SignSGD и матричному обновлению Muon.","q":"","v":false,"source_url":"https://arxiv.org/abs/2506.04430","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Анализ безградиентных вариантов рассматривает сходимость при шумных вычислениях функции с постоянным числом запросов оракула на итерацию.","q":"","v":false,"source_url":"https://arxiv.org/abs/2506.04430","locator":"Аннотация arXiv"},{"k":"empirical","s":"Методы проверены в дообучении языковых моделей с ограничениями по памяти; используются вычисления функции без хранения графа обратного распространения.","q":"","v":false,"source_url":"https://arxiv.org/abs/2506.04430","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2506.04430","venue_url":"https://arxiv.org/abs/2506.04430","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00014","ax":"2506.02724","key":null,"t":"WeightLoRA: Keep Only Necessary Adapters","au":"Andrey Veprikov, Vladimir Solodkin, Alexander Zyl, Andrey Savchenko, Aleksandr Beznosikov","y":2026,"v":"ACL 2026","s":"WeightLoRA выбирает, какие адаптеры LoRA действительно нужны для задачи. Обучаемые веса позволяют оставить значимые адаптеры и сократить число обучаемых параметров.","sr":"WeightLoRA выбирает, какие адаптеры LoRA действительно нужны для задачи. Обучаемые веса позволяют оставить значимые адаптеры и сократить число обучаемых параметров.","ab":"WeightLoRA выбирает, какие адаптеры LoRA действительно нужны для задачи. Обучаемые веса позволяют оставить значимые адаптеры и сократить число обучаемых параметров.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"WeightLoRA назначает адаптерам обучаемые веса и использует их, чтобы выбирать необходимые для задачи адаптеры LoRA.","q":"","v":false,"source_url":"https://aclanthology.org/2026.acl-long.566/","locator":"Аннотация ACL 2026"},{"k":"method","s":"Отбор адаптеров уменьшает число обучаемых параметров по сравнению с размещением LoRA во всех выбранных заранее слоях.","q":"","v":false,"source_url":"https://aclanthology.org/2026.acl-long.566/","locator":"Аннотация ACL 2026"},{"k":"method","s":"WeightLoRA+ развивает процедуру отбора адаптеров, сохраняя задачу совместного выбора их вклада и дообучения модели.","q":"","v":false,"source_url":"https://aclanthology.org/2026.acl-long.566/","locator":"Аннотация ACL 2026"},{"k":"empirical","s":"Авторы сравнивают число параметров и качество на задачах понимания и генерации текста с DeBERTa, BART, Llama и Qwen. Сокращение адаптеров проверяется вместе с качеством ответа.","q":"","v":false,"source_url":"https://aclanthology.org/2026.acl-long.566/","locator":"Аннотация ACL 2026"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2506.02724","venue_url":"https://aclanthology.org/2026.acl-long.566/","code_url":"https://github.com/brain-lab-research/WLoRA","reading_scope":"Аннотация ACL 2026"},{"id":"pub00015","ax":"2409.10442","key":null,"t":"New Aspects of Black Box Conditional Gradient: Variance Reduction and One Point Feedback","au":"Andrey Veprikov, Aleksandr Bogdanov, Vladislav Minashkin, Aleksandr Beznosikov","y":2024,"v":"Chaos, Solitons & Fractals · 2024","s":"JAGUAR сохраняет координатную информацию для безградиентной оптимизации. Память позволяет строить обновления условного градиента и градиентного спуска с малым числом новых вычислений функции.","sr":"JAGUAR сохраняет координатную информацию для безградиентной оптимизации. Память позволяет строить обновления условного градиента и градиентного спуска с малым числом новых вычислений функции.","ab":"JAGUAR сохраняет координатную информацию для безградиентной оптимизации. Память позволяет строить обновления условного градиента и градиентного спуска с малым числом новых вычислений функции.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"JAGUAR переиспользует ранее полученные оценки координат, снижая число новых вызовов функции на итерацию до постоянного.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.10442","locator":"Аннотация arXiv"},{"k":"method","s":"Память координат встраивается в безградиентные варианты Frank–Wolfe и градиентного спуска.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.10442","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Анализ охватывает выпуклые и невыпуклые задачи, а также условие Поляка — Лоясиевича.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.10442","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Рассматриваются детерминированные и стохастические шумные оракулы; для разных режимов выведены соответствующие оценки сложности.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.10442","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2409.10442","venue_url":"https://doi.org/10.1016/j.chaos.2024.115654","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00016","ax":"2408.01848","key":null,"t":"Methods for Optimization Problems with Markovian Stochasticity and Non-Euclidean Geometry","au":"Vladimir Solodkin, Andrey Veprikov, Alexander Chernyavskiy, Aleksandr Beznosikov","y":2026,"v":"AAAI 2026","s":"Работа изучает оптимизацию с зависимыми марковскими наблюдениями в неевклидовой геометрии. Зеркальный спуск применяется к выпуклой минимизации и вариационным неравенствам.","sr":"Работа изучает оптимизацию с зависимыми марковскими наблюдениями в неевклидовой геометрии. Зеркальный спуск применяется к выпуклой минимизации и вариационным неравенствам.","ab":"Работа изучает оптимизацию с зависимыми марковскими наблюдениями в неевклидовой геометрии. Зеркальный спуск применяется к выпуклой минимизации и вариационным неравенствам.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"Четыре варианта зеркального спуска приспособлены к стохастическим наблюдениям, связанным марковской цепью.","q":"","v":false,"source_url":"https://arxiv.org/abs/2408.01848","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Оценки сходимости учитывают зависимость наблюдений и неевклидову геометрию вместо предположения о независимом евклидовом шуме.","q":"","v":false,"source_url":"https://arxiv.org/abs/2408.01848","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Рассмотрены гладкая выпуклая минимизация и вариационные неравенства с липшицевым монотонным оператором.","q":"","v":false,"source_url":"https://arxiv.org/abs/2408.01848","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Нижние оценки сложности сопоставляются с полученными верхними оценками для обоснования оптимальности в рассмотренных постановках.","q":"","v":false,"source_url":"https://arxiv.org/abs/2408.01848","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2408.01848","venue_url":"https://ojs.aaai.org/index.php/AAAI/article/view/39746","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00017","ax":"2405.02726","key":null,"t":"A Mathematical Model of the Hidden Feedback Loop Effect in Machine Learning Systems","au":"Andrey Veprikov, Alexander Afanasyev, Anton Khritankov","y":2025,"v":"Knowledge and Information Systems · 2025","s":"Модель скрытой обратной связи описывает цикл: данные обучают модель, её решения меняют среду, а новая среда порождает следующие данные. Исследуются долгосрочные последствия повторного обучения.","sr":"Модель скрытой обратной связи описывает цикл: данные обучают модель, её решения меняют среду, а новая среда порождает следующие данные. Исследуются долгосрочные последствия повторного обучения.","ab":"Модель скрытой обратной связи описывает цикл: данные обучают модель, её решения меняют среду, а новая среда порождает следующие данные. Исследуются долгосрочные последствия повторного обучения.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"definition","s":"Скрытая обратная связь возникает, когда состояние среды причинно зависит от предсказаний обученной модели и тем самым меняет распределение будущих данных.","q":"","v":false,"source_url":"https://arxiv.org/abs/2405.02726","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Динамическая модель повторного обучения задаёт достаточные условия сходимости и предельные множества распределений.","q":"","v":false,"source_url":"https://arxiv.org/abs/2405.02726","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Положительная и отрицательная обратная связь рассмотрены как разные режимы эволюции распределения данных.","q":"","v":false,"source_url":"https://arxiv.org/abs/2405.02726","locator":"Аннотация arXiv"},{"k":"empirical","s":"Предсказания модели проверены на двух синтетических наборах данных; экспериментальная часть не является проверкой промышленной рекомендательной системы.","q":"","v":false,"source_url":"https://arxiv.org/abs/2405.02726","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2405.02726","venue_url":"https://doi.org/10.1007/s10115-025-02560-w","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00018","ax":"2307.00392","key":null,"t":"Non-Smooth Setting of Stochastic Decentralized Convex Optimization Problem Over Time-Varying Graphs","au":"Aleksandr Lobanov, Andrew Veprikov, Georgiy Konin, Aleksandr Beznosikov, Alexander Gasnikov, Dmitry Kovalev","y":2023,"v":"Computational Management Science · 2023","s":"Децентрализованная выпуклая оптимизация изучается на графе, чьи связи меняются со временем. Для негладких локальных функций используются стохастические безградиентные оценки и случайное сглаживание.","sr":"Децентрализованная выпуклая оптимизация изучается на графе, чьи связи меняются со временем. Для негладких локальных функций используются стохастические безградиентные оценки и случайное сглаживание.","ab":"Децентрализованная выпуклая оптимизация изучается на графе, чьи связи меняются со временем. Для негладких локальных функций используются стохастические безградиентные оценки и случайное сглаживание.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"definition","s":"Каждый агент хранит свою локальную функцию и обменивается информацией только с соседями по меняющемуся графу связи.","q":"","v":false,"source_url":"https://arxiv.org/abs/2307.00392","locator":"Аннотация arXiv"},{"k":"method","s":"Случайное сглаживание в евклидовой геометрии переводит негладкую задачу в форму, пригодную для безградиентных обновлений.","q":"","v":false,"source_url":"https://arxiv.org/abs/2307.00392","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Получены оценки сходимости для стохастической децентрализованной выпуклой оптимизации с меняющейся связностью.","q":"","v":false,"source_url":"https://arxiv.org/abs/2307.00392","locator":"Аннотация arXiv"},{"k":"empirical","s":"Численные эксперименты сопоставляют поведение предложенных методов с предсказаниями теоретического анализа.","q":"","v":false,"source_url":"https://arxiv.org/abs/2307.00392","locator":"Аннотация arXiv"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2307.00392","venue_url":"https://doi.org/10.1007/s10287-023-00479-7","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"pub00019","ax":null,"key":null,"t":"Adversarial Robustness through Wide Local Minima: A Simple Training Technique","au":"Andrey S. Veprikov, Anton S. Khritankov, Sergey A. Smirnov","y":2024,"v":"ICOMP 2024","s":"Работа связывает устойчивость к состязательным возмущениям с шириной локального минимума. Авторы исследуют, как настройки обучения помогают находить такие решения без изменения архитектуры модели.","sr":"Работа связывает устойчивость к состязательным возмущениям с шириной локального минимума. Авторы исследуют, как настройки обучения помогают находить такие решения без изменения архитектуры модели.","ab":"Работа связывает устойчивость к состязательным возмущениям с шириной локального минимума. Авторы исследуют, как настройки обучения помогают находить такие решения без изменения архитектуры модели.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"Предложено подбирать параметры обучения так, чтобы направлять оптимизацию к широким локальным минимумам.","q":"","v":false,"source_url":"https://openreview.net/pdf?id=oZ8j2xSWVg","locator":"Аннотация и введение, стр. 1–2"},{"k":"method","s":"Подход к повышению устойчивости использует настройки обучения без изменения архитектуры, функции потерь или добавления состязательных примеров в обучающую выборку.","q":"","v":false,"source_url":"https://openreview.net/pdf?id=oZ8j2xSWVg","locator":"Аннотация и введение, стр. 1–2"},{"k":"empirical","s":"В работе исследуется устойчивость к атаке FGSM на MNIST; этот результат относится к конкретной атаке и экспериментальной постановке.","q":"","v":false,"source_url":"https://openreview.net/pdf?id=oZ8j2xSWVg","locator":"Аннотация и введение, стр. 1–2"}],"origin":"author-publication","source_url":"https://openreview.net/pdf?id=oZ8j2xSWVg","venue_url":"https://openreview.net/forum?id=oZ8j2xSWVg","code_url":null,"reading_scope":"Аннотация и введение, стр. 1–2"},{"id":"pub00020","ax":null,"key":null,"t":"On the Properties of the Limit Set of a Repeated Machine Learning Process under Feature Space Transformations","au":"Andrey S. Veprikov, Anton S. Khritankov","y":2025,"v":"Искусственный интеллект и принятие решений · 2025","s":"Работа изучает, когда изменение пространства признаков сохраняет прогноз долгосрочного поведения системы с повторным обучением. Это позволяет исследовать сложную систему через более простую модель.","sr":"Работа изучает, когда изменение пространства признаков сохраняет прогноз долгосрочного поведения системы с повторным обучением. Это позволяет исследовать сложную систему через более простую модель.","ab":"Работа изучает, когда изменение пространства признаков сохраняет прогноз долгосрочного поведения системы с повторным обучением. Это позволяет исследовать сложную систему через более простую модель.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"definition","s":"При многократном машинном обучении следующие обучающие данные зависят от поведения пользователей и уже работающей модели.","q":"","v":false,"source_url":"https://journals.rcsi.science/2071-8594/article/view/293493","locator":"Аннотация издателя"},{"k":"theoretical","s":"Исследованы условия переноса прогноза асимптотического поведения между исходным и преобразованным пространствами признаков.","q":"","v":false,"source_url":"https://journals.rcsi.science/2071-8594/article/view/293493","locator":"Аннотация издателя"},{"k":"theoretical","s":"При выполнении этих условий системы меньшей размерности могут служить моделями для изучения предельного поведения более сложных систем.","q":"","v":false,"source_url":"https://journals.rcsi.science/2071-8594/article/view/293493","locator":"Аннотация издателя"}],"origin":"author-publication","source_url":"https://journals.rcsi.science/2071-8594/article/view/293493","venue_url":"https://journals.rcsi.science/2071-8594/article/view/293493","code_url":null,"reading_scope":"Аннотация издателя"},{"id":"pub00021","ax":null,"key":null,"t":"Zero Order Algorithm for Decentralized Optimization Problems","au":"A. S. Veprikov, E. D. Petrov, G. V. Evseev, A. N. Beznosikov","y":2024,"v":"Доклады РАН / Doklady Mathematics · 2024","s":"ZO-MARINA переносит распределённую оптимизацию MARINA в постановку чёрного ящика. Устройства используют шумные значения локальных функций и обмениваются разреженными оценками обновлений.","sr":"ZO-MARINA переносит распределённую оптимизацию MARINA в постановку чёрного ящика. Устройства используют шумные значения локальных функций и обмениваются разреженными оценками обновлений.","ab":"ZO-MARINA переносит распределённую оптимизацию MARINA в постановку чёрного ящика. Устройства используют шумные значения локальных функций и обмениваются разреженными оценками обновлений.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"ZO-MARINA заменяет точные градиенты оценками по значениям функции, а обычный компрессор — разностями оценок на выбранных координатах.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562424602336","locator":"Аннотация издателя"},{"k":"method","s":"Безградиентное разреживание позволяет каждому устройству выполнять постоянное число вызовов оракула на итерацию.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562424602336","locator":"§1.2 Main Contributions"},{"k":"theoretical","s":"Анализ сходимости охватывает невыпуклые функции и условие Поляка — Лоясиевича; полученные оценки сопоставляются с методами первого порядка.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562424602336","locator":"Аннотация издателя"},{"k":"empirical","s":"Вычислительные эксперименты посвящены подбору гиперпараметров ResNet-18 на CIFAR-10 и SVM на наборах mushroom и MNIST-784.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562424602336","locator":"§1.2 Main Contributions"}],"origin":"author-publication","source_url":"https://link.springer.com/article/10.1134/S1064562424602336","venue_url":"https://link.springer.com/article/10.1134/S1064562424602336","code_url":null,"reading_scope":"Аннотация издателя; §1.2 Main Contributions"},{"id":"pub00022","ax":null,"key":null,"t":"Sampling of Semiorthogonal Matrices for the Muon Algorithm","au":"E. D. Petrov, G. V. Evseev, A. V. Antonov, A. S. Veprikov, N. A. Bushkov, S. V. Moiseev, A. N. Beznosikov","y":2025,"v":"Доклады РАН / Doklady Mathematics · 2025","s":"Исследуются способы семплирования полуортогональных матриц для безградиентного Muon. Работа сравнивает, как выбор матричных направлений влияет на стоимость и качество дообучения LLM.","sr":"Исследуются способы семплирования полуортогональных матриц для безградиентного Muon. Работа сравнивает, как выбор матричных направлений влияет на стоимость и качество дообучения LLM.","ab":"Исследуются способы семплирования полуортогональных матриц для безградиентного Muon. Работа сравнивает, как выбор матричных направлений влияет на стоимость и качество дообучения LLM.","f":"Публикации Андрея/Статьи и препринты","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"В безградиентной постановке Muon использует оценки по прямым проходам модели, избегая обратного распространения и хранения его графа.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562425700565","locator":"Аннотация издателя"},{"k":"method","s":"Разные способы семплирования полуортогональных направлений учитывают матричную структуру параметров при построении обновления.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562425700565","locator":"Аннотация издателя"},{"k":"empirical","s":"В работе сравниваются стратегии семплирования по качеству дообучения языковых моделей и вычислительной эффективности.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562425700565","locator":"Аннотация издателя"}],"origin":"author-publication","source_url":"https://link.springer.com/article/10.1134/S1064562425700565","venue_url":"https://link.springer.com/article/10.1134/S1064562425700565","code_url":null,"reading_scope":"Аннотация издателя"},{"id":"ref00001","ax":"2106.09685","key":null,"t":"LoRA: Low-Rank Adaptation of Large Language Models","au":"Edward J. Hu, Yelong Shen, Phillip Wallis, Zeyuan Allen-Zhu, Yuanzhi Li, Shean Wang, Lu Wang, Weizhu Chen","y":2021,"v":"arXiv · 2021","s":"LoRA дообучает небольшие низкоранговые добавки к замороженным весам модели. Это сокращает число обучаемых параметров и расход памяти при адаптации к новой задаче.","sr":"LoRA дообучает небольшие низкоранговые добавки к замороженным весам модели. Это сокращает число обучаемых параметров и расход памяти при адаптации к новой задаче.","ab":"LoRA дообучает небольшие низкоранговые добавки к замороженным весам модели. Это сокращает число обучаемых параметров и расход памяти при адаптации к новой задаче.","f":"Другие исследования/Статьи по теме","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"LoRA замораживает предобученные веса и добавляет обучаемые низкоранговые матрицы в слои Transformer.","q":"","v":false,"source_url":"https://arxiv.org/abs/2106.09685","locator":"Аннотация arXiv"},{"k":"empirical","s":"В экспериментах с RoBERTa, DeBERTa, GPT-2 и GPT-3 авторы получают качество на уровне полного дообучения или выше при меньшем числе обучаемых параметров.","q":"","v":false,"source_url":"https://arxiv.org/abs/2106.09685","locator":"Аннотация arXiv"},{"k":"method","s":"Низкоранговую добавку можно объединить с исходными весами, поэтому подход не требует дополнительных слоёв при инференсе.","q":"","v":false,"source_url":"https://arxiv.org/abs/2106.09685","locator":"Аннотация arXiv"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2106.09685","venue_url":"https://arxiv.org/abs/2106.09685","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"ref00002","ax":"2303.10512","key":null,"t":"AdaLoRA: Adaptive Budget Allocation for Parameter-Efficient Fine-Tuning","au":"Qingru Zhang, Minshuo Chen, Alexander Bukharin, Nikos Karampatziakis, Pengcheng He, Yu Cheng, Weizhu Chen, Tuo Zhao","y":2023,"v":"arXiv · 2023","s":"AdaLoRA распределяет бюджет обучаемых параметров между матрицами по их важности. Вместо одинакового ранга для всех обновлений метод сокращает менее полезные компоненты.","sr":"AdaLoRA распределяет бюджет обучаемых параметров между матрицами по их важности. Вместо одинакового ранга для всех обновлений метод сокращает менее полезные компоненты.","ab":"AdaLoRA распределяет бюджет обучаемых параметров между матрицами по их важности. Вместо одинакового ранга для всех обновлений метод сокращает менее полезные компоненты.","f":"Другие исследования/Статьи по теме","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"AdaLoRA адаптивно распределяет бюджет параметров между матрицами весов по оценке важности обновлений.","q":"","v":false,"source_url":"https://arxiv.org/abs/2303.10512","locator":"Аннотация arXiv"},{"k":"method","s":"Обновления параметризованы в форме сингулярного разложения: неважные сингулярные значения отсекаются без дорогого точного SVD.","q":"","v":false,"source_url":"https://arxiv.org/abs/2303.10512","locator":"Аннотация arXiv"},{"k":"empirical","s":"На задачах обработки языка, ответов на вопросы и генерации авторы сообщают улучшения относительно базовых методов, особенно при малом бюджете параметров.","q":"","v":false,"source_url":"https://arxiv.org/abs/2303.10512","locator":"Аннотация arXiv"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2303.10512","venue_url":"https://arxiv.org/abs/2303.10512","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"ref00003","ax":"2305.17333","key":null,"t":"Fine-Tuning Language Models with Just Forward Passes","au":"Sadhika Malladi, Tianyu Gao, Eshaan Nichani, Alex Damian, Jason D. Lee, Danqi Chen, Sanjeev Arora","y":2023,"v":"arXiv · 2023","s":"MeZO дообучает языковую модель только прямыми проходами, оценивая направление обновления по значениям целевой функции. Основная цель — экономия памяти без обратного распространения.","sr":"MeZO дообучает языковую модель только прямыми проходами, оценивая направление обновления по значениям целевой функции. Основная цель — экономия памяти без обратного распространения.","ab":"MeZO дообучает языковую модель только прямыми проходами, оценивая направление обновления по значениям целевой функции. Основная цель — экономия памяти без обратного распространения.","f":"Другие исследования/Статьи по теме","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"MeZO реализует безградиентный SGD с изменением параметров на месте и оценивает обновление через прямые проходы модели.","q":"","v":false,"source_url":"https://arxiv.org/abs/2305.17333","locator":"Аннотация arXiv"},{"k":"empirical","s":"Авторы проверяют метод на классификации, выборе ответа и генерации. В их реализации расход памяти при дообучении сопоставим с инференсом.","q":"","v":false,"source_url":"https://arxiv.org/abs/2305.17333","locator":"Аннотация arXiv"},{"k":"method","s":"Метод совместим с полным дообучением, LoRA и prefix tuning и допускает недифференцируемые цели, например accuracy или F1.","q":"","v":false,"source_url":"https://arxiv.org/abs/2305.17333","locator":"Аннотация arXiv"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2305.17333","venue_url":"https://arxiv.org/abs/2305.17333","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"ref00004","ax":"1802.09568","key":null,"t":"Shampoo: Preconditioned Stochastic Tensor Optimization","au":"Vineet Gupta, Tomer Koren, Yoram Singer","y":2018,"v":"arXiv · 2018","s":"Shampoo предобусловливает обновления с учётом тензорной структуры параметров. Набор матриц по отдельным осям заменяет одну огромную матрицу предобусловливания.","sr":"Shampoo предобусловливает обновления с учётом тензорной структуры параметров. Набор матриц по отдельным осям заменяет одну огромную матрицу предобусловливания.","ab":"Shampoo предобусловливает обновления с учётом тензорной структуры параметров. Набор матриц по отдельным осям заменяет одну огромную матрицу предобусловливания.","f":"Другие исследования/Статьи по теме","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"Shampoo хранит отдельную матрицу предобусловливания для каждого измерения тензора параметров, сворачивая градиенты по остальным измерениям.","q":"","v":false,"source_url":"https://arxiv.org/abs/1802.09568","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Для стохастической выпуклой оптимизации авторы доказывают гарантии сходимости с помощью матричных следовых неравенств.","q":"","v":false,"source_url":"https://arxiv.org/abs/1802.09568","locator":"Аннотация arXiv"},{"k":"empirical","s":"В экспериментах авторы наблюдают более быструю сходимость, чем у сравниваемых оптимизаторов, при сопоставимом времени шага. Это результат приведённых задач, а не гарантия для любой модели.","q":"","v":false,"source_url":"https://arxiv.org/abs/1802.09568","locator":"Аннотация arXiv"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/1802.09568","venue_url":"https://arxiv.org/abs/1802.09568","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"ref00005","ax":"1610.02132","key":null,"t":"QSGD: Communication-Efficient SGD via Gradient Quantization and Encoding","au":"Dan Alistarh, Demjan Grubic, Jerry Li, Ryota Tomioka, Milan Vojnovic","y":2016,"v":"arXiv · 2016","s":"QSGD уменьшает объём передаваемых градиентов с помощью квантования и кодирования. Уровень сжатия задаёт компромисс между стоимостью связи и временем сходимости.","sr":"QSGD уменьшает объём передаваемых градиентов с помощью квантования и кодирования. Уровень сжатия задаёт компромисс между стоимостью связи и временем сходимости.","ab":"QSGD уменьшает объём передаваемых градиентов с помощью квантования и кодирования. Уровень сжатия задаёт компромисс между стоимостью связи и временем сходимости.","f":"Другие исследования/Статьи по теме","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"QSGD сжимает градиентные обновления на каждом узле через квантование и кодирование перед передачей другим участникам обучения.","q":"","v":false,"source_url":"https://arxiv.org/abs/1610.02132","locator":"Аннотация arXiv"},{"k":"theoretical","s":"При стандартных предположениях семейство схем сохраняет гарантии сходимости и позволяет управлять компромиссом между объёмом сообщений и числом итераций.","q":"","v":false,"source_url":"https://arxiv.org/abs/1610.02132","locator":"Аннотация arXiv"},{"k":"empirical","s":"Авторы проверяют квантование на классификации изображений и распознавании речи и сообщают сокращение затрат на связь и полного времени обучения в этих экспериментах.","q":"","v":false,"source_url":"https://arxiv.org/abs/1610.02132","locator":"Аннотация arXiv"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/1610.02132","venue_url":"https://arxiv.org/abs/1610.02132","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"ref00006","ax":"2002.06673","key":null,"t":"Performative Prediction","au":"Juan C. Perdomo, Tijana Zrnic, Celestine Mendler-Dünner, Moritz Hardt","y":2020,"v":"arXiv · 2020","s":"Работа рассматривает модели, чьи предсказания меняют будущие данные. Она вводит понятие устойчивости повторного обучения в среде, которая реагирует на предсказатель.","sr":"Работа рассматривает модели, чьи предсказания меняют будущие данные. Она вводит понятие устойчивости повторного обучения в среде, которая реагирует на предсказатель.","ab":"Работа рассматривает модели, чьи предсказания меняют будущие данные. Она вводит понятие устойчивости повторного обучения в среде, которая реагирует на предсказатель.","f":"Другие исследования/Статьи по теме","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"definition","s":"Предсказание является перформативным, если решения, принятые на его основе, влияют на предсказываемый результат и распределение будущих данных.","q":"","v":false,"source_url":"https://arxiv.org/abs/2002.06673","locator":"Аннотация arXiv"},{"k":"definition","s":"Перформативная устойчивость описывает равновесие: модель оптимальна для распределения, которое возникает в ответ на применение этой модели.","q":"","v":false,"source_url":"https://arxiv.org/abs/2002.06673","locator":"Аннотация arXiv"},{"k":"theoretical","s":"Авторы изучают условия, при которых повторное переобучение сходится к устойчивой точке с почти минимальным риском, и связывают подход со стратегической классификацией.","q":"","v":false,"source_url":"https://arxiv.org/abs/2002.06673","locator":"Аннотация arXiv"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2002.06673","venue_url":"https://arxiv.org/abs/2002.06673","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"ref00007","ax":"2406.09405","key":null,"t":"Why Warmup the Learning Rate? Underlying Mechanisms and Improvements","au":"Dayal Singh Kalra, Maissam Barkeshli","y":2024,"v":"arXiv · 2024","s":"Авторы исследуют, почему постепенное увеличение шага в начале обучения помогает SGD и Adam. Разогрев связывается с переходом в области, допускающие больший целевой шаг.","sr":"Авторы исследуют, почему постепенное увеличение шага в начале обучения помогает SGD и Adam. Разогрев связывается с переходом в области, допускающие больший целевой шаг.","ab":"Авторы исследуют, почему постепенное увеличение шага в начале обучения помогает SGD и Adam. Разогрев связывается с переходом в области, допускающие больший целевой шаг.","f":"Другие исследования/Статьи по теме","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"В систематических экспериментах с SGD и Adam основная польза разогрева связана с возможностью использовать больший целевой шаг обучения.","q":"","v":false,"source_url":"https://arxiv.org/abs/2406.09405","locator":"Аннотация arXiv"},{"k":"empirical","s":"Поведение в период разогрева зависит от инициализации и параметризации: резкость ландшафта может сначала расти либо снижаться.","q":"","v":false,"source_url":"https://arxiv.org/abs/2406.09405","locator":"Аннотация arXiv"},{"k":"method","s":"Авторы предлагают выбирать начальный шаг с учётом механизма loss catapult и рассматривают инициализацию дисперсии Adam, дающую сходные с разогревом преимущества.","q":"","v":false,"source_url":"https://arxiv.org/abs/2406.09405","locator":"Аннотация arXiv"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2406.09405","venue_url":"https://arxiv.org/abs/2406.09405","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"ref00008","ax":"2409.11321","key":null,"t":"SOAP: Improving and Stabilizing Shampoo using Adam","au":"Nikhil Vyas, Depen Morwani, Rosie Zhao, Mujin Kwun, Itai Shapira, David Brandfonbrener, Lucas Janson, Sham Kakade","y":2024,"v":"arXiv · 2024","s":"SOAP применяет Adam в собственном базисе предобусловливателя Shampoo. Метод позволяет реже обновлять этот базис, продолжая накапливать статистики градиента между обновлениями.","sr":"SOAP применяет Adam в собственном базисе предобусловливателя Shampoo. Метод позволяет реже обновлять этот базис, продолжая накапливать статистики градиента между обновлениями.","ab":"SOAP применяет Adam в собственном базисе предобусловливателя Shampoo. Метод позволяет реже обновлять этот базис, продолжая накапливать статистики градиента между обновлениями.","f":"Другие исследования/Статьи по теме","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"SOAP выполняет шаги Adam в собственном базисе предобусловливателя, связывая покоординатную адаптацию с геометрией Shampoo.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.11321","locator":"Аннотация arXiv"},{"k":"method","s":"Статистика второго момента обновляется на каждом шаге в текущем базисе. Это смягчает ухудшение качества при редком пересчёте собственного разложения.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.11321","locator":"Аннотация arXiv"},{"k":"empirical","s":"На предобучении языковых моделей с 360 и 660 миллионами параметров авторы сообщают выигрыш по итерациям и времени относительно AdamW и Shampoo в режиме большого батча.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.11321","locator":"Аннотация arXiv"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2409.11321","venue_url":"https://arxiv.org/abs/2409.11321","code_url":null,"reading_scope":"Аннотация arXiv"},{"id":"demo0001","ax":null,"key":"ivanova2025how","t":"How Long Should Warm-up Be? A Budget View","au":"Ivanova, Maria, Sokolov, Peter","y":2025,"v":"","s":"Учебная статья. Статья разбирает разогрев как долю бюджета обучения, а не как отдельное число шагов. Основной вывод: доля, а не абсолютная длина, переносится между масштабами.","sr":"Учебная статья. Статья разбирает разогрев как долю бюджета обучения, а не как отдельное число шагов. Основной вывод: доля, а не абсолютная длина, переносится между масштабами.","ab":"Учебная статья. Статья разбирает разогрев как долю бюджета обучения, а не как отдельное число шагов. Основной вывод: доля, а не абсолютная длина, переносится между масштабами.","f":"Optimization/schedules","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Доля разогрева 0.6% от горизонта даёт лучший лосс на трёх размерах модели.","q":"","v":false},{"k":"theoretical","s":"Нижняя граница на длину разогрева растёт как корень из размера батча.","q":"","v":false},{"k":"method","s":"Признак остановки разогрева считается по норме обновления в окне ста шагов.","q":"","v":false}]},{"id":"demo0002","ax":null,"key":"romanov2024warmup","t":"Warm-up Is Not About Curvature","au":"Romanov, Dmitry","y":2024,"v":"","s":"Учебная статья. Работа проверяет объяснение разогрева через кривизну и показывает, что оно не воспроизводится: разогрев помогает и там, где кривизна на старте мала.","sr":"Учебная статья. Работа проверяет объяснение разогрева через кривизну и показывает, что оно не воспроизводится: разогрев помогает и там, где кривизна на старте мала.","ab":"Учебная статья. Работа проверяет объяснение разогрева через кривизну и показывает, что оно не воспроизводится: разогрев помогает и там, где кривизна на старте мала.","f":"Optimization/schedules","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Разогрев помогает и при малой кривизне на старте обучения.","q":"","v":false},{"k":"definition","s":"Кривизна на старте измеряется как максимальное собственное значение гессиана на первых десяти шагах.","q":"","v":false}]},{"id":"demo0003","ax":null,"key":"sokolov2025constant","t":"Constant Step Instead of Decay: What Is Lost","au":"Sokolov, Peter, Ivanova, Maria","y":2025,"v":"","s":"Учебная статья. Статья сравнивает постоянный шаг и косинусное затухание при равном бюджете и показывает, где разрыв закрывается удлинением горизонта.","sr":"Учебная статья. Статья сравнивает постоянный шаг и косинусное затухание при равном бюджете и показывает, где разрыв закрывается удлинением горизонта.","ab":"Учебная статья. Статья сравнивает постоянный шаг и косинусное затухание при равном бюджете и показывает, где разрыв закрывается удлинением горизонта.","f":"Optimization/schedules","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Постоянный шаг проигрывает косинусу 0.02 по лоссу при равном бюджете.","q":"","v":false},{"k":"empirical","s":"Разрыв закрывается при удвоении горизонта.","q":"","v":false}]},{"id":"demo0004","ax":null,"key":"romanov2026short","t":"A Short Note on Schedules and Seeds","au":"Romanov, Dmitry, Ivanova, Maria","y":2026,"v":"","s":"Учебная статья. Заметка о том, что разброс по сидам сопоставим с разрывом между расписаниями, и о том, сколько сидов нужно, чтобы разрыв стал видимым.","sr":"Учебная статья. Заметка о том, что разброс по сидам сопоставим с разрывом между расписаниями, и о том, сколько сидов нужно, чтобы разрыв стал видимым.","ab":"Учебная статья. Заметка о том, что разброс по сидам сопоставим с разрывом между расписаниями, и о том, сколько сидов нужно, чтобы разрыв стал видимым.","f":"Optimization/schedules","th":null,"nc":1,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Разброс по трём сидам составляет 0.003 по валидационному лоссу.","q":"","v":false}]},{"id":"demo0005","ax":null,"key":"kovalenko2024second","t":"Second Moment Estimates Under Distribution Shift","au":"Kovalenko, Anna","y":2024,"v":"","s":"Учебная статья. Работа показывает, где оценка второго момента перестаёт отражать масштаб градиента, и предлагает диагностику этого случая.","sr":"Учебная статья. Работа показывает, где оценка второго момента перестаёт отражать масштаб градиента, и предлагает диагностику этого случая.","ab":"Учебная статья. Работа показывает, где оценка второго момента перестаёт отражать масштаб градиента, и предлагает диагностику этого случая.","f":"Optimization/adaptive","th":null,"nc":1,"ns":1,"nm":0,"c":[{"k":"theoretical","s":"При смене распределения данных оценка второго момента отстаёт на время своего окна усреднения.","q":"","v":false}]},{"id":"demo0006","ax":null,"key":"kovalenko2025when","t":"When Adaptive Methods Do Not Help","au":"Kovalenko, Anna, Sokolov, Peter","y":2025,"v":"","s":"Учебная статья. Статья собирает случаи, где адаптивность не даёт выигрыша, и связывает их с однородностью масштабов градиента по слоям.","sr":"Учебная статья. Статья собирает случаи, где адаптивность не даёт выигрыша, и связывает их с однородностью масштабов градиента по слоям.","ab":"Учебная статья. Статья собирает случаи, где адаптивность не даёт выигрыша, и связывает их с однородностью масштабов градиента по слоям.","f":"Optimization/adaptive","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"empirical","s":"При однородных масштабах градиента адаптивность не даёт выигрыша.","q":"","v":false},{"k":"method","s":"Однородность масштабов проверяется отношением максимальной и медианной нормы по слоям.","q":"","v":false}]},{"id":"demo0007","ax":null,"key":"ivanova2025compute","t":"Compute-Optimal Training Revisited","au":"Ivanova, Maria, Kovalenko, Anna, Romanov, Dmitry","y":2025,"v":"","s":"Учебная статья. Работа перепроверяет соотношение размера модели и объёма данных при фиксированном бюджете и уточняет показатель на длинных горизонтах.","sr":"Учебная статья. Работа перепроверяет соотношение размера модели и объёма данных при фиксированном бюджете и уточняет показатель на длинных горизонтах.","ab":"Учебная статья. Работа перепроверяет соотношение размера модели и объёма данных при фиксированном бюджете и уточняет показатель на длинных горизонтах.","f":"LLM/scaling","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"empirical","s":"На длинных горизонтах оптимальное отношение данных к параметрам выше классической оценки.","q":"","v":false},{"k":"theoretical","s":"Показатель степени в законе масштабирования устойчив к смене расписания шага.","q":"","v":false}]},{"id":"demo0008","ax":null,"key":"sokolov2026cheap","t":"Cheap Proxies for Scaling Laws","au":"Sokolov, Peter","y":2026,"v":"","s":"Учебная статья. Статья предлагает считать закон масштабирования по коротким прогонам и показывает, где такая оценка ломается.","sr":"Учебная статья. Статья предлагает считать закон масштабирования по коротким прогонам и показывает, где такая оценка ломается.","ab":"Учебная статья. Статья предлагает считать закон масштабирования по коротким прогонам и показывает, где такая оценка ломается.","f":"LLM/scaling","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"method","s":"Закон масштабирования оценивается по прогонам длиной в десятую часть горизонта.","q":"","v":false},{"k":"empirical","s":"Оценка по коротким прогонам ошибается на масштабах, где меняется расписание.","q":"","v":false}]},{"id":"demo0009","ax":null,"key":"demo2026example9","t":"Gradient Clipping During Warm-up","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Клиппинг и разогрев влияют на разные признаки стабильности.","sr":"Учебная статья. Клиппинг и разогрев влияют на разные признаки стабильности.","ab":"Учебная статья. Клиппинг и разогрев влияют на разные признаки стабильности.","f":"Optimization/stability","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Клиппинг снижает частоту выбросов, но не задаёт длину разогрева.","q":"","v":false},{"k":"method","s":"Сравнение использует один порядок данных и одинаковый бюджет.","q":"","v":false},{"k":"definition","s":"Выброс — превышение нормы над заранее заданным порогом.","q":"","v":false}]},{"id":"demo0010","ax":null,"key":"demo2026example10","t":"Short Windows and False Stops","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Узкое окно быстрее реагирует на шум нормы обновления.","sr":"Учебная статья. Узкое окно быстрее реагирует на шум нормы обновления.","ab":"Учебная статья. Узкое окно быстрее реагирует на шум нормы обновления.","f":"Optimization/stability","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"В учебных траекториях окно 20 даёт больше ложных остановок, чем окно 100.","q":"","v":false},{"k":"method","s":"Частота ложных остановок считается на независимых контрольных траекториях.","q":"","v":false},{"k":"definition","s":"Ложная остановка определяется до выбора ширины окна.","q":"","v":false}]},{"id":"demo0011","ax":null,"key":"demo2026example11","t":"Numerical Precision at the Start of Training","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Формат вычислений проверяется вместе с расписанием.","sr":"Учебная статья. Формат вычислений проверяется вместе с расписанием.","ab":"Учебная статья. Формат вычислений проверяется вместе с расписанием.","f":"Optimization/stability","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Учебная пара BF16/FP32 имеет небольшой разрыв качества и разную память.","q":"","v":false},{"k":"method","s":"Для сравнения фиксируются данные, сид и число обновлений.","q":"","v":false},{"k":"definition","s":"Нечисловое значение учитывается как сбой, а не как плохой лосс.","q":"","v":false}]},{"id":"demo0012","ax":null,"key":"demo2026example12","t":"Warm-up Transfer Across Two Corpora","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Перенос между корпусами требует нового контроля.","sr":"Учебная статья. Перенос между корпусами требует нового контроля.","ab":"Учебная статья. Перенос между корпусами требует нового контроля.","f":"LLM/data","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"На двух готовых парах виден небольшой разрыв, третья ещё выполняется.","q":"","v":false},{"k":"method","s":"Сравниваются перенос настройки и местный подбор на новом корпусе.","q":"","v":false},{"k":"definition","s":"Предварительный результат содержит число завершённых пар.","q":"","v":false}]},{"id":"demo0013","ax":null,"key":"demo2026example13","t":"Data Order as a Control Variable","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Порядок данных может скрыть эффект расписания.","sr":"Учебная статья. Порядок данных может скрыть эффект расписания.","ab":"Учебная статья. Порядок данных может скрыть эффект расписания.","f":"LLM/data","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"В учебном сравнении смена порядка дала разброс, сопоставимый с эффектом расписания.","q":"","v":false},{"k":"method","s":"Парный дизайн использует один порядок данных для обоих методов.","q":"","v":false},{"k":"definition","s":"Сид задаёт воспроизводимый порядок, но не заменяет описание выборки.","q":"","v":false}]},{"id":"demo0014","ax":null,"key":"demo2026example14","t":"Separate Validation for Schedule Selection","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Выбор настройки и итоговая оценка требуют разных данных.","sr":"Учебная статья. Выбор настройки и итоговая оценка требуют разных данных.","ab":"Учебная статья. Выбор настройки и итоговая оценка требуют разных данных.","f":"LLM/data","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Учебный пример показывает завышение качества при многократном подборе на одной валидации.","q":"","v":false},{"k":"method","s":"Настройка выбирается на промежуточном наборе и оценивается на отложенном.","q":"","v":false},{"k":"definition","s":"Утечка оценки возникает, когда итоговый набор участвует в выборе параметров.","q":"","v":false}]},{"id":"demo0015","ax":null,"key":"demo2026example15","t":"Restarting Without Changing the Next Step","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Для рестарта одних весов недостаточно.","sr":"Учебная статья. Для рестарта одних весов недостаточно.","ab":"Учебная статья. Для рестарта одних весов недостаточно.","f":"LLM/reproducibility","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Полная контрольная точка воспроизводит следующий шаг в детерминированном учебном примере.","q":"","v":false},{"k":"method","s":"Сохраняются веса, оптимизатор, генераторы случайности и позиция данных.","q":"","v":false},{"k":"definition","s":"Проверка рестарта сопоставляет непрерывный и восстановленный запуски.","q":"","v":false}]},{"id":"demo0016","ax":null,"key":"demo2026example16","t":"Accumulation and the Schedule Clock","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Индекс расписания должен соответствовать обновлениям.","sr":"Учебная статья. Индекс расписания должен соответствовать обновлениям.","ab":"Учебная статья. Индекс расписания должен соответствовать обновлениям.","f":"LLM/reproducibility","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Учебный запуск с индексом по микробатчам завершал разогрев в четыре раза раньше.","q":"","v":false},{"k":"method","s":"Индекс увеличивается после шага оптимизатора.","q":"","v":false},{"k":"definition","s":"Четыре микробатча могут составлять один эффективный батч.","q":"","v":false}]},{"id":"demo0017","ax":null,"key":"demo2026example17","t":"Reporting Failed Runs","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Неудачный запуск остаётся частью истории исследования.","sr":"Учебная статья. Неудачный запуск остаётся частью истории исследования.","ab":"Учебная статья. Неудачный запуск остаётся частью истории исследования.","f":"LLM/reproducibility","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Отказ по памяти не дал оценки качества, но зафиксировал ограничение конфигурации.","q":"","v":false},{"k":"method","s":"Отдельно сохраняются причина отказа, последний шаг и следующий проверяемый план.","q":"","v":false},{"k":"definition","s":"Неудачный прогон и опровергнутое научное утверждение — разные записи.","q":"","v":false}]},{"id":"demo0018","ax":null,"key":"demo2026example18","t":"Time to a Shared Quality Target","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Сравнение времени требует общего порога качества.","sr":"Учебная статья. Сравнение времени требует общего порога качества.","ab":"Учебная статья. Сравнение времени требует общего порога качества.","f":"Evaluation/efficiency","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"В учебных пяти запусках косинус достиг порога раньше постоянного шага.","q":"","v":false},{"k":"method","s":"Заранее фиксируются порог, бюджет и правило учёта не достигших его запусков.","q":"","v":false},{"k":"definition","s":"Время до порога не равно длительности всего обучения.","q":"","v":false}]},{"id":"demo0019","ax":null,"key":"demo2026example19","t":"Why One Seed Can Reverse the Ranking","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Один случайный запуск может выбрать другого победителя.","sr":"Учебная статья. Один случайный запуск может выбрать другого победителя.","ab":"Учебная статья. Один случайный запуск может выбрать другого победителя.","f":"Evaluation/efficiency","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"В учебной таблице лидер первого сида проиграл по среднему пяти.","q":"","v":false},{"k":"method","s":"Публикуются среднее, разброс и все индивидуальные результаты.","q":"","v":false},{"k":"definition","s":"Парная разность сравнивает методы внутри одного и того же сида.","q":"","v":false}]},{"id":"demo0020","ax":null,"key":"demo2026example20","t":"Memory Budgets and Effective Batch Size","au":"Demo Methods Group (вымышленные авторы)","y":2026,"v":"","s":"Учебная статья. Ограничение памяти не требует менять эффективный батч.","sr":"Учебная статья. Ограничение памяти не требует менять эффективный батч.","ab":"Учебная статья. Ограничение памяти не требует менять эффективный батч.","f":"Evaluation/efficiency","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Учебное накопление градиента снизило пиковую память при том же эффективном батче.","q":"","v":false},{"k":"method","s":"Сравнение фиксирует нормировку градиента и число обновлений.","q":"","v":false},{"k":"definition","s":"Микробатч задаёт память прохода, эффективный батч — данные одного шага.","q":"","v":false}]}],"folders":[{"f":"Публикации Андрея/Статьи и препринты","n":22},{"f":"Другие исследования/Статьи по теме","n":8},{"f":"Optimization/schedules","n":4},{"f":"Optimization/adaptive","n":2},{"f":"LLM/scaling","n":2},{"f":"Optimization/stability","n":3},{"f":"LLM/data","n":3},{"f":"LLM/reproducibility","n":3},{"f":"Evaluation/efficiency","n":3}],"links":[]};
